use crate::AuditError;
use std::collections::BTreeSet;
const CLAIM:&str="SYNTHETIC_GFM_CAPABILITY_PASSPORT_ONLY_NOT_PHYSICAL_QUALIFICATION_OR_GRID_CODE_CONFORMITY";
const EPS:f64=1e-9;
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum GfmCapability{VoltageFrequencyAdaptability,PowerQuality,ActivePowerControl,ReactivePowerControl,PrimaryFrequencyRegulation,VoltageReactivePowerRegulation,InertiaResponse,PowerOscillationDamping,VoltageTolerance,PhaseAngleJumpTolerance,GfmGflModeSwitching,BlackStartCapability,BlackStartFromZeroVoltage,IslandedLoadPickup,GridLossResynchronisation,LoadFollowingFrequencyVoltageDroop,WeakGridScrSweep,UnbalancedFaultNegativeSequence,MultiVendorInteroperability,SystemLevelDisturbance}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum TestBoundary{Unit,Plant,System}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum EvidenceStage{VendorDeclaration,Synthetic,OfflineSimulation,SoftwareInLoop,ControllerHardwareInLoop,PowerHardwareInLoop,Laboratory,Commissioning,OperationalField}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum EvidenceClass{VendorAssertion,Modelled,Synthetic,Measured,Witnessed,Accredited}
#[derive(Debug,Clone,Copy,PartialEq,Eq)] pub enum ObservationStatus{Pass,Fail,Inconclusive,Invalid,Stale}
#[derive(Debug,Clone,PartialEq)] pub struct MetricCriterion{pub metric_id:String,pub unit:String,pub minimum:Option<f64>,pub maximum:Option<f64>,pub measurement_boundary_id:String,pub sample_window_id:String}
#[derive(Debug,Clone,PartialEq)] pub struct RequiredTestEvidence{pub test_id:String,pub required_stage:EvidenceStage,pub minimum_pass_count:u32,pub maximum_failures:u32}
#[derive(Debug,Clone,PartialEq)] pub struct GfmCapabilityClaim{pub claim_id:String,pub capability:GfmCapability,pub boundary:TestBoundary,pub qualified_configuration_sha256:String,pub topology_sha256:String,pub operating_envelope_sha256:String,pub acceptance_contract_id:String,pub acceptance_contract_sha256:String,pub required_test_evidence:Vec<RequiredTestEvidence>}
#[derive(Debug,Clone,PartialEq)] pub struct GfmTestProtocol{pub test_id:String,pub capability:GfmCapability,pub boundary:TestBoundary,pub protocol_sha256:String,pub qualified_configuration_sha256:String,pub topology_sha256:String,pub operating_envelope_sha256:String,pub initial_operating_point_sha256:String,pub disturbance_sha256:String,pub measurement_boundary_id:String,pub instrument_calibration_sha256:String,pub timebase_sha256:String,pub acceptance_contract_id:String,pub acceptance_contract_sha256:String,pub metric_criteria:Vec<MetricCriterion>}
#[derive(Debug,Clone,PartialEq)] pub struct MetricMeasurement{pub metric_id:String,pub value:f64,pub absolute_uncertainty:f64,pub unit:String,pub measurement_boundary_id:String,pub sample_window_id:String}
#[derive(Debug,Clone,PartialEq)] pub struct GfmTestObservation{pub observation_id:String,pub test_id:String,pub protocol_sha256:String,pub evidence_stage:EvidenceStage,pub evidence_class:EvidenceClass,pub raw_bundle_sha256:String,pub analysis_build_sha256:String,pub verification_receipt_reference:String,pub measurements:Vec<MetricMeasurement>}
#[derive(Debug,Clone,PartialEq)] pub struct GfmCapabilityPassport{pub passport_id:String,pub product_id:String,pub claims:Vec<GfmCapabilityClaim>,pub protocols:Vec<GfmTestProtocol>,pub observations:Vec<GfmTestObservation>}
#[derive(Debug,Clone,PartialEq)] pub struct GfmObservationResult{pub observation_id:String,pub test_id:String,pub evidence_stage:EvidenceStage,pub status:ObservationStatus,pub reasons:Vec<String>}
#[derive(Debug,Clone,PartialEq)] pub struct GfmClaimQualification{pub claim_id:String,pub qualified:bool,pub required_test_count:usize,pub satisfied_test_count:usize,pub missing_or_insufficient_requirements:Vec<String>,pub failed_observation_ids:Vec<String>,pub inconclusive_observation_ids:Vec<String>,pub invalid_observation_ids:Vec<String>,pub stale_observation_ids:Vec<String>}
#[derive(Debug,Clone,PartialEq)] pub struct GfmCapabilityPassportReport{pub passport_id:String,pub product_id:String,pub claim_results:Vec<GfmClaimQualification>,pub observation_results:Vec<GfmObservationResult>,pub claim_ceiling:&'static str}
impl GfmCapabilityPassportReport{pub const fn claim_ceiling(&self)->&'static str{CLAIM}}
fn nb(s:&str)->bool{!s.trim().is_empty()} fn dg(s:&str)->bool{s.len()==64&&s.bytes().all(|b|b.is_ascii_hexdigit())}
fn uniq(xs:impl IntoIterator<Item=String>,n:&str)->Result<(),AuditError>{let mut h=BTreeSet::new();for x in xs{if !nb(&x)||!h.insert(x.clone()){return Err(AuditError(format!("{n} must be non-empty and unique: {x:?}")));}}Ok(())}
fn stage_class(s:EvidenceStage,c:EvidenceClass)->bool{match c{EvidenceClass::VendorAssertion=>s==EvidenceStage::VendorDeclaration,EvidenceClass::Modelled=>matches!(s,EvidenceStage::OfflineSimulation|EvidenceStage::SoftwareInLoop),EvidenceClass::Synthetic=>s==EvidenceStage::Synthetic,EvidenceClass::Measured|EvidenceClass::Witnessed|EvidenceClass::Accredited=>matches!(s,EvidenceStage::ControllerHardwareInLoop|EvidenceStage::PowerHardwareInLoop|EvidenceStage::Laboratory|EvidenceStage::Commissioning|EvidenceStage::OperationalField)}}
fn check_criterion(c:&MetricCriterion)->Result<(),AuditError>{if !nb(&c.metric_id)||!nb(&c.unit)||!nb(&c.measurement_boundary_id)||!nb(&c.sample_window_id)||(c.minimum.is_none()&&c.maximum.is_none())||c.minimum.is_some_and(|x|!x.is_finite())||c.maximum.is_some_and(|x|!x.is_finite())||matches!((c.minimum,c.maximum),(Some(a),Some(b))if a>b){return Err(AuditError(format!("bad criterion {:?}",c.metric_id)));}Ok(())}
fn check_protocol(p:&GfmTestProtocol)->Result<(),AuditError>{if !nb(&p.test_id)||![&p.protocol_sha256,&p.qualified_configuration_sha256,&p.topology_sha256,&p.operating_envelope_sha256,&p.initial_operating_point_sha256,&p.disturbance_sha256,&p.instrument_calibration_sha256,&p.timebase_sha256,&p.acceptance_contract_sha256].iter().all(|x|dg(x))||!nb(&p.measurement_boundary_id)||!nb(&p.acceptance_contract_id)||p.metric_criteria.is_empty(){return Err(AuditError(format!("incomplete protocol {:?}",p.test_id)));}uniq(p.metric_criteria.iter().map(|x|x.metric_id.clone()),"protocol metric")?;for c in &p.metric_criteria{check_criterion(c)?;if c.measurement_boundary_id!=p.measurement_boundary_id{return Err(AuditError(format!("metric {:?} boundary differs from protocol boundary",c.metric_id)));}}Ok(())}
fn check_claim(c:&GfmCapabilityClaim,ps:&[GfmTestProtocol])->Result<(),AuditError>{if !nb(&c.claim_id)||![&c.qualified_configuration_sha256,&c.topology_sha256,&c.operating_envelope_sha256,&c.acceptance_contract_sha256].iter().all(|x|dg(x))||!nb(&c.acceptance_contract_id)||c.required_test_evidence.is_empty(){return Err(AuditError(format!("incomplete claim {:?}",c.claim_id)));}uniq(c.required_test_evidence.iter().map(|x|format!("{}::{:?}",x.test_id,x.required_stage)),"claim requirement")?;for r in &c.required_test_evidence{if !nb(&r.test_id)||r.minimum_pass_count==0{return Err(AuditError("invalid required test".into()));}let p=ps.iter().find(|p|p.test_id==r.test_id).ok_or_else(||AuditError(format!("missing test {}",r.test_id)))?;if p.capability!=c.capability||p.boundary!=c.boundary||p.qualified_configuration_sha256!=c.qualified_configuration_sha256||p.topology_sha256!=c.topology_sha256||p.operating_envelope_sha256!=c.operating_envelope_sha256||p.acceptance_contract_id!=c.acceptance_contract_id||p.acceptance_contract_sha256!=c.acceptance_contract_sha256{return Err(AuditError(format!("claim/test mismatch {}",r.test_id)));}}Ok(())}
fn metric(c:&MetricCriterion,m:&MetricMeasurement)->Result<ObservationStatus,String>{if m.metric_id!=c.metric_id||m.unit!=c.unit||m.measurement_boundary_id!=c.measurement_boundary_id||m.sample_window_id!=c.sample_window_id||!m.value.is_finite()||!m.absolute_uncertainty.is_finite()||m.absolute_uncertainty<0.0{return Err(format!("metric {:?} context/uncertainty invalid",c.metric_id));}let lo=m.value-m.absolute_uncertainty;let hi=m.value+m.absolute_uncertainty;if c.minimum.is_some_and(|x|hi<x-EPS)||c.maximum.is_some_and(|x|lo>x+EPS){return Ok(ObservationStatus::Fail);}if c.minimum.is_some_and(|x|lo<x-EPS)||c.maximum.is_some_and(|x|hi>x+EPS){return Ok(ObservationStatus::Inconclusive);}Ok(ObservationStatus::Pass)}
fn eval_obs(o:&GfmTestObservation,p:Option<&GfmTestProtocol>)->GfmObservationResult{let make=|s,r|GfmObservationResult{observation_id:o.observation_id.clone(),test_id:o.test_id.clone(),evidence_stage:o.evidence_stage,status:s,reasons:r};let Some(p)=p else{return make(ObservationStatus::Invalid,vec!["unknown protocol".into()]);};if o.protocol_sha256!=p.protocol_sha256{return make(ObservationStatus::Stale,vec!["protocol digest stale".into()]);}let mut reasons=Vec::new();if !stage_class(o.evidence_stage,o.evidence_class){reasons.push("evidence class incompatible with stage".into());}if !dg(&o.raw_bundle_sha256)||!dg(&o.analysis_build_sha256){reasons.push("raw bundle or analysis digest invalid".into());}if !nb(&o.verification_receipt_reference){reasons.push("verification receipt reference missing".into());}if uniq(o.measurements.iter().map(|m|m.metric_id.clone()),"measurement metric").is_err()||o.measurements.len()!=p.metric_criteria.len(){reasons.push("metric set incomplete/duplicated".into());}if !reasons.is_empty(){return make(ObservationStatus::Invalid,reasons);}let(mut fail,mut inc)=(false,false);for c in &p.metric_criteria{let Some(m)=o.measurements.iter().find(|m|m.metric_id==c.metric_id)else{reasons.push(format!("missing metric {}",c.metric_id));continue;};match metric(c,m){Ok(ObservationStatus::Fail)=>{fail=true;reasons.push(format!("metric {} outside range",c.metric_id));},Ok(ObservationStatus::Inconclusive)=>{inc=true;reasons.push(format!("metric {} uncertainty overlaps limit",c.metric_id));},Ok(ObservationStatus::Pass)=>(),_=>reasons.push("invalid metric".into())}}let s=if fail{ObservationStatus::Fail}else if inc{ObservationStatus::Inconclusive}else if !reasons.is_empty(){ObservationStatus::Invalid}else{ObservationStatus::Pass};make(s,reasons)}
/// Checks a claim -> protocol -> observation chain. Acceptance thresholds are
/// project/jurisdiction-owned. This does not authenticate evidence bytes or operate equipment.
pub fn validate_gfm_capability_passport(p:&GfmCapabilityPassport)->Result<GfmCapabilityPassportReport,AuditError>{if !nb(&p.passport_id)||!nb(&p.product_id)||p.claims.is_empty()||p.protocols.is_empty(){return Err(AuditError("passport identity/claims/protocols incomplete".into()));}uniq(p.claims.iter().map(|x|x.claim_id.clone()),"claim ID")?;uniq(p.protocols.iter().map(|x|x.test_id.clone()),"test ID")?;uniq(p.observations.iter().map(|x|x.observation_id.clone()),"observation ID")?;for x in &p.protocols{check_protocol(x)?;}for x in &p.claims{check_claim(x,&p.protocols)?;}let obs:Vec<_>=p.observations.iter().map(|o|eval_obs(o,p.protocols.iter().find(|x|x.test_id==o.test_id))).collect();let mut claims=Vec::new();for c in &p.claims{let(mut satisfied,mut missing)=(0,Vec::new());let(mut failed,mut inc,mut invalid,mut stale)=(Vec::new(),Vec::new(),Vec::new(),Vec::new());for req in &c.required_test_evidence{let rows:Vec<_>=obs.iter().filter(|o|o.test_id==req.test_id&&o.evidence_stage==req.required_stage).collect();for o in &rows{match o.status{ObservationStatus::Fail=>failed.push(o.observation_id.clone()),ObservationStatus::Inconclusive=>inc.push(o.observation_id.clone()),ObservationStatus::Invalid=>invalid.push(o.observation_id.clone()),ObservationStatus::Stale=>stale.push(o.observation_id.clone()),ObservationStatus::Pass=>()}}let passes=rows.iter().filter(|o|o.status==ObservationStatus::Pass).count();let fails=rows.iter().filter(|o|o.status==ObservationStatus::Fail).count();if passes<req.minimum_pass_count as usize||fails>req.maximum_failures as usize{missing.push(format!("{}::{:?} passes {passes}/{}, failures {fails}/{}",req.test_id,req.required_stage,req.minimum_pass_count,req.maximum_failures));}else{satisfied+=1;}}claims.push(GfmClaimQualification{claim_id:c.claim_id.clone(),qualified:missing.is_empty(),required_test_count:c.required_test_evidence.len(),satisfied_test_count:satisfied,missing_or_insufficient_requirements:missing,failed_observation_ids:failed,inconclusive_observation_ids:inc,invalid_observation_ids:invalid,stale_observation_ids:stale});}claims.sort_by(|a,b|a.claim_id.cmp(&b.claim_id));Ok(GfmCapabilityPassportReport{passport_id:p.passport_id.clone(),product_id:p.product_id.clone(),claim_results:claims,observation_results:obs,claim_ceiling:CLAIM})}

#[cfg(test)]mod tests{use super::*;fn h(c:char)->String{std::iter::repeat(c).take(64).collect()}fn proto(id:&str,cap:GfmCapability,b:TestBoundary)->GfmTestProtocol{GfmTestProtocol{test_id:id.into(),capability:cap,boundary:b,protocol_sha256:h('1'),qualified_configuration_sha256:h('2'),topology_sha256:h('3'),operating_envelope_sha256:h('4'),initial_operating_point_sha256:h('5'),disturbance_sha256:h('6'),measurement_boundary_id:"poc".into(),instrument_calibration_sha256:h('7'),timebase_sha256:h('8'),acceptance_contract_id:"contract".into(),acceptance_contract_sha256:h('9'),metric_criteria:vec![MetricCriterion{metric_id:"droop".into(),unit:"percent".into(),minimum:Some(0.0),maximum:Some(2.0),measurement_boundary_id:"poc".into(),sample_window_id:"steady".into()},MetricCriterion{metric_id:"settling".into(),unit:"ms".into(),minimum:Some(0.0),maximum:Some(500.0),measurement_boundary_id:"poc".into(),sample_window_id:"post".into()}]}}fn obs(id:&str,test:&str,stage:EvidenceStage,class:EvidenceClass,v:f64,u:f64)->GfmTestObservation{GfmTestObservation{observation_id:id.into(),test_id:test.into(),protocol_sha256:h('1'),evidence_stage:stage,evidence_class:class,raw_bundle_sha256:h('a'),analysis_build_sha256:h('b'),verification_receipt_reference:"synthetic://receipt".into(),measurements:vec![MetricMeasurement{metric_id:"droop".into(),value:v,absolute_uncertainty:u,unit:"percent".into(),measurement_boundary_id:"poc".into(),sample_window_id:"steady".into()},MetricMeasurement{metric_id:"settling".into(),value:420.0,absolute_uncertainty:20.0,unit:"ms".into(),measurement_boundary_id:"poc".into(),sample_window_id:"post".into()}]}}fn claim(id:&str,test:&str,stage:EvidenceStage,cap:GfmCapability,b:TestBoundary)->GfmCapabilityClaim{GfmCapabilityClaim{claim_id:id.into(),capability:cap,boundary:b,qualified_configuration_sha256:h('2'),topology_sha256:h('3'),operating_envelope_sha256:h('4'),acceptance_contract_id:"contract".into(),acceptance_contract_sha256:h('9'),required_test_evidence:vec![RequiredTestEvidence{test_id:test.into(),required_stage:stage,minimum_pass_count:1,maximum_failures:0}]}}fn p()->GfmCapabilityPassport{GfmCapabilityPassport{passport_id:"synthetic-passport".into(),product_id:"synthetic-unit".into(),claims:vec![claim("synthetic-droop","droop",EvidenceStage::Synthetic,GfmCapability::PrimaryFrequencyRegulation,TestBoundary::Unit),claim("field-black-start","black-start",EvidenceStage::OperationalField,GfmCapability::BlackStartFromZeroVoltage,TestBoundary::System)],protocols:vec![proto("droop",GfmCapability::PrimaryFrequencyRegulation,TestBoundary::Unit),proto("black-start",GfmCapability::BlackStartFromZeroVoltage,TestBoundary::System)],observations:vec![obs("obs-droop","droop",EvidenceStage::Synthetic,EvidenceClass::Synthetic,1.0,0.1),obs("obs-black-start","black-start",EvidenceStage::Synthetic,EvidenceClass::Synthetic,1.0,0.1)]}}
#[test]fn synthetic_does_not_satisfy_field_claim(){let r=validate_gfm_capability_passport(&p()).unwrap();assert!(r.claim_results.iter().find(|c|c.claim_id=="synthetic-droop").unwrap().qualified);assert!(!r.claim_results.iter().find(|c|c.claim_id=="field-black-start").unwrap().qualified);}
#[test]fn vendor_assertion_cannot_be_field_measurement(){let mut x=p();x.observations[0].evidence_stage=EvidenceStage::OperationalField;x.observations[0].evidence_class=EvidenceClass::VendorAssertion;let r=validate_gfm_capability_passport(&x).unwrap();assert!(r.observation_results.iter().any(|o|o.status==ObservationStatus::Invalid));}
#[test]fn uncertainty_crossing_bound_is_inconclusive(){let mut x=p();x.observations[0].measurements[0].value=1.95;x.observations[0].measurements[0].absolute_uncertainty=0.1;let r=validate_gfm_capability_passport(&x).unwrap();assert!(r.observation_results.iter().any(|o|o.status==ObservationStatus::Inconclusive));}
#[test]fn outside_range_fails(){let mut x=p();x.observations[0].measurements[0].value=3.0;let r=validate_gfm_capability_passport(&x).unwrap();assert!(r.observation_results.iter().any(|o|o.status==ObservationStatus::Fail));}
#[test]fn incomplete_measurements_invalid(){let mut x=p();x.observations[0].measurements.pop();let r=validate_gfm_capability_passport(&x).unwrap();assert!(r.observation_results.iter().any(|o|o.status==ObservationStatus::Invalid));}
#[test]fn measurement_boundary_mismatch_invalid(){let mut x=p();x.observations[0].measurements[0].measurement_boundary_id="battery-terminal".into();let r=validate_gfm_capability_passport(&x).unwrap();assert!(r.observation_results.iter().any(|o|o.status==ObservationStatus::Invalid));}
#[test]fn protocol_digest_change_stales_old_result(){let mut x=p();x.protocols[0].protocol_sha256=h('c');let r=validate_gfm_capability_passport(&x).unwrap();assert!(r.observation_results.iter().any(|o|o.status==ObservationStatus::Stale));}
#[test]fn configuration_mismatch_rejected(){let mut x=p();x.protocols[0].qualified_configuration_sha256=h('d');assert!(validate_gfm_capability_passport(&x).is_err());}
#[test]fn acceptance_contract_mismatch_rejected(){let mut x=p();x.protocols[0].acceptance_contract_sha256=h('d');assert!(validate_gfm_capability_passport(&x).is_err());}
#[test]fn duplicate_protocol_metric_rejected(){let mut x=p();x.protocols[0].metric_criteria[1].metric_id="droop".into();assert!(validate_gfm_capability_passport(&x).is_err());}
#[test]fn duplicate_test_stage_requirement_rejected(){let mut x=p();let y=x.claims[0].required_test_evidence[0].clone();x.claims[0].required_test_evidence.push(y);assert!(validate_gfm_capability_passport(&x).is_err());}
#[test]fn required_pass_count_enforced(){let mut x=p();x.claims[0].required_test_evidence[0].minimum_pass_count=2;let r=validate_gfm_capability_passport(&x).unwrap();assert!(!r.claim_results.iter().find(|c|c.claim_id=="synthetic-droop").unwrap().qualified);}
#[test]fn failed_repeat_blocks_claim(){let mut x=p();x.observations.push(obs("fail","droop",EvidenceStage::Synthetic,EvidenceClass::Synthetic,3.0,0.1));let r=validate_gfm_capability_passport(&x).unwrap();assert!(!r.claim_results.iter().find(|c|c.claim_id=="synthetic-droop").unwrap().qualified);}
#[test]fn bad_raw_digest_invalid(){let mut x=p();x.observations[0].raw_bundle_sha256="bad".into();let r=validate_gfm_capability_passport(&x).unwrap();assert!(r.observation_results.iter().any(|o|o.status==ObservationStatus::Invalid));}
#[test]fn unit_claim_cannot_be_promoted_to_plant(){let mut x=p();x.protocols[0].boundary=TestBoundary::Plant;assert!(validate_gfm_capability_passport(&x).is_err());}
#[test]fn topology_digest_bound(){let mut x=p();x.claims[0].topology_sha256=h('d');assert!(validate_gfm_capability_passport(&x).is_err());}
#[test]fn duplicate_observation_id_rejected(){let mut x=p();let duplicate=x.observations[0].clone();x.observations.push(duplicate);assert!(validate_gfm_capability_passport(&x).is_err());}
#[test]fn metric_boundary_must_match_protocol_boundary(){let mut x=p();x.protocols[0].metric_criteria[0].measurement_boundary_id="battery-terminal".into();assert!(validate_gfm_capability_passport(&x).is_err());}
}
